import {BASE,HOLE,SHAFT,ATRIUM_IDS,FLOOR_PANELS,GLASS_BAYS} from './atrium-layout.js';import{atriumChannels}from'./atrium-physics.js';import{BY_ID,boundaryWalls}from'./architecture.js';import{toLocal}from'./pose.js';
export function atriumMapSVG(s){const c=atriumChannels(s),rect=(r,color,extra='')=>`<rect x="${r.x}" y="${r.z}" width="${r.w}" height="${r.d}" fill="${color}" ${extra}/>`;let out='<svg xmlns="http://www.w3.org/2000/svg" viewBox="-1 -4 54 24" role="img" aria-label="吹き抜け専用三段平面図・中間段は施設の第四層ではありません">';for(const [i,id]of ATRIUM_IDS.entries()){const b=BY_ID[id],p=s.positions[id];out+=`<g data-id="${id}" transform="translate(${i*18} 0)"><text x="0" y="-2.8" font-size=".9">${id} / 基準Y ${p.y.toFixed(1)}m</text><text x="0" y="-1.5" font-size=".6">X ${p.x}・Z ${p.z} / 4CH一体</text>`+rect({x:0,z:0,w:16,d:16},b.color);for(const l of[...boundaryWalls(b),...b.walls])out+=`<line x1="${l.a[0]}" y1="${l.a[1]}" x2="${l.b[0]}" y2="${l.b[1]}" stroke="#435c5b" stroke-width=".12"/>`;out+=rect(HOLE,i>0&&c.floor>.001?'#263c42':'#d2d8b8','data-hatch="central"');if(i>0)out+=rect(SHAFT,c.ceiling>.001?'#263c42':'#bcc6ac');for(const r of GLASS_BAYS)if(i>0)out+=rect(r,'#6b998f','fill-opacity=".35"');if(i>0&&c.guard>.01)out+=rect(HOLE,'none','stroke="#2a8886" stroke-width=".16"');for(const r of FLOOR_PANELS)if(i>0)out+=rect({...r,x:r.x+r.dx*c.floor,z:r.z+r.floorDz*c.floor},'none','stroke="#69796e" stroke-dasharray=".2 .2" stroke-width=".07"');if(i<2)for(let n=1;n<=33;n++)out+=rect({x:12,z:13.2-n*.26,w:2.4,d:.26},'#a0a58e','stroke="#626c5b" stroke-width=".035"');if(s.owner===id){const q=toLocal(p,s.player);out+=`<circle cx="${q.x}" cy="${q.z}" r=".35" fill="#cc6045"/><text x="0" y="17.8" font-size=".65">現在 +${q.y.toFixed(2)}m</text>`;}out+=`<text x="0" y="19" font-size=".6">歩行床 +${(BASE+.16).toFixed(2)}m / ${c.ready?'三段接続':'閉鎖・接続準備'}</text></g>`;}return out+'</svg>';}
